extern "C" int sprintf(char *, const char *, ...);
extern "C" char *strcat(char *, const char *);

class stringx
{
  char *chars;
  void *my_buf;

public:
  stringx();
  stringx(const char *, int = -1);
  ~stringx();
  stringx &operator=(const stringx &);
  const char *c_str() const { return chars; }
};

class entity_track_tree
{
public:
  static const char *extension();
};

class entity
{
public:
  void load_anim(const stringx &) const;
};

bool file_finder_exists(const stringx &, const stringx &, stringx * = 0);

class generic_anim
{
public:
  generic_anim(const stringx& path, const stringx& name) { my_base_name = name; dummy = false; cur_state = cur_anim = 0; left_down = right_down = false; };
  virtual ~generic_anim() {}
  virtual void update(bool, bool, bool, float *) = 0;
  virtual void spawn() = 0;
  virtual void switch_anims() = 0;

protected:
  stringx my_base_name;
  int cur_state, cur_anim;
  bool dummy;
  bool left_down, right_down;
};

class generic_anim_ice : public generic_anim
{
public:
  generic_anim_ice(entity *entity, const stringx& path, const stringx& name);
  virtual ~generic_anim_ice() {}
  void update(bool, bool, bool, float *);
  void spawn();
  void switch_anims();

private:
  static const char* generic_anim_names[];
  int generic_anims[3];
  int generic_anim_state;
  entity *my_entity;
};

generic_anim_ice::generic_anim_ice (entity *entity, const stringx& path, const stringx& name)
	: generic_anim (path, name)
{
	my_entity = entity;

  for (int i = 0; i < 3; i++)
  {
    generic_anims[i] = 0;

    for (;;)
    {
      char anim[256];
      sprintf (anim, "%s\\ANIMATIONS\\%s_%s_%d", path.c_str(), name.c_str(), generic_anim_names[i], generic_anims[i] + 1);

      if (file_finder_exists (anim, entity_track_tree::extension ()))
      {
        strcat (anim, entity_track_tree::extension ());
        my_entity->load_anim (anim);
        generic_anims[i]++;
      }
      else
        break;
    }
  }
}
